mapper.select:
SELECT

FROM t_train_stock
WHERE train_id = #{trainId}
  AND seat_type = #{seatType}
LIMIT 1

mapper.update:
UPDATE t_train_stock
SET available_count = available_count - 1,
    version = version + 1
WHERE id = #{id}
  AND version = #{version}
  AND available_count > 0

UPDATE t_train_stock
SET available_count = #{availableCount},
    total_count = #{totalCount},
    price = #{price}
WHERE id = #{id}
